require('dotenv').config();               // carrega .env
const { Client, GatewayIntentBits } = require('discord.js');
const axios = require('axios');
const { SlashCommandBuilder } = require('@discordjs/slash-command');

// ---------- CONFIGURAÇÕES ----------
const DISCORD_TOKEN = process.env.DISCORDANTOKEN;
if (!DISCORDANTOKEN) throw new Error('Variável DISCORDANTOKEN não definida!');
const API_BASE_URL = process.env.YOUR_API_URL;
if (!API_BASE_URL) throw new Error('Variável YOUR_API_URL não definida!');

// ---------- INSTANCIAÇÃO DO CLIENTE ----------
const client = new Client({
  intents: [GatewayIntentBits.Guilds], // permite ler mensagens e responder
});

// ---------- FUNÇÕES AUXILIARES ----------

/**
 * Extrai o primeiro link http(s) do conteúdo da mensagem.
 * Retorna o valor encontrado ou null.
 */
function extractLink(content) {
  const match = content.match(/^(https?:\/\/)?(www\.)?[^\s]+/);
  return match ? match[0].trim() : null;
}

/**
 * Chama a sua API e devolve o objeto JSON retornado.
 * Ajuste os parâmetros conforme a assinatura da sua API.
 */
async function callApi(link) {
  // Exemplo: GET /pdf/{link} → { text: "...", metadata: {...} }
  const url = `${API_BASE_URL}/pdf/${link}`;
  try {
    const resp = await axios.get(url); // troque por POST se necessário
    return resp.data;
  } catch (err) {
    console.error(`Erro ao chamar API para ${link}:`, err.response?.data || err.message);
    return {};
  }
}

/**
 * Formata o resultado para o usuário.
 * Retorna um objeto pronto para ser usado em `chat.replyTo`.
 */
function formatResult(originalLink, apiResponse) {
  return {
    original_link: originalLink,
    extracted_text: apiResponse.text ?? '',
    metadata: apiResponse.metadata ?? {},
  };
}

// ---------- LISTENAS DE EVENTS ----------

/**
 * Processa mensagens que contêm um link.
 * Se encontrar um link, chama a API e responde.
 */
async function handleLink(message) {
  const content = message.content.trim();

  // Ignora mensagens que começam com '#' (comandos)
  if (content.startsWith('#')) return;

  const link = extractLink(content);
  if (!link) return; // sem link válido

  // Chama a API
  const apiData = await callApi(link);

  // Monta a resposta formatada
  const result = formatResult(link, apiData);

  // Responde ao usuário
  client.chat.replyTo(message.user, `✅ Informação obtida!\n\n` + JSON.stringify(result, null, 2));
}

/**
 * Tratamento de comando slash `/extract <link>`
 */
async function handleExtractCommand(user) {
  const args = user.args;
  if (!args.length || !args[0]) {
    return client.chat.sendUser(
      user.id,
      '❓ Use `/extract <link>` para enviar um link de PDF.'
    );
  }

  const rawLink = args[0].trim().startsWith('http') ? args[0] : `https://example.com/${args[0]}`;
  // Aqui você pode fazer mais validações (ex.: verificar se é realmente um PDF)
  await handleLink(new Message({ content: rawLink })); // simula um novo message
}

// ---------- REGISTROS DE EVENTOS ----------

client.on('messageCreate', async (msg) => {
  // ignora mensagens de comandos (começam com #)
  if (msg.content && msg.content.startsWith('#')) return;

  // procura por um link http(s) no conteúdo
  const linkMatch = msg.content.match(/^(https?:\/\/)?(www\.)?[^\s]+/);
  if (linkMatch) {
    await handleLink(msg);
  }
});

// Slash command setup
const extractCmd = new SlashCommandBuilder()
  .setName('extract')
  .setDescription('Extrair informações de um PDF enviado como link.')
  .addText('Send a PDF link', false) // opcional: texto do comando
  .action(async ({ user, content }) => {
    // O argumento `content` vem como string do link
    const link = content.trim();
    if (!link || !link.startsWith('http')) {
      return client.chat.sendUser(user, '❌ Por favor, forneça um link válido.');
    }
    await handleLink(new Message({ content: link })); // repassa para o handler de mensagem
  });

client.onSetupSlashCommand(extractCmd);

// ---------- LOGIN ----------
await client.login(DISCORDANTOKEN);
console.log('Bot logado com sucesso!');

// ---------- PONTO DE ENTRADA ----------
// Para rodar localmente:
//   node index.js
```

#### Explicação rápida dos blocos principais

| Bloco | Função |
|------|--------|
| **Configurações** | Lê tokens e a URL da sua API. |
| **`extractLink`** | Regex simples para pegar o primeiro URL (http/https) no texto da mensagem. |
| **`callApi`** | Faz uma requisição `GET` (mude para `POST` se precisar) e devolve `response.data`. |
| **`formatResult`** | Montando o JSON que veio da API de forma legível. |
| **`handleLink`** | Detecta um link, chama a API e responde ao usuário com `client.chat.replyTo`. |
| **`handleExtractCommand`** | Comando slash que espera um argumento (link) e delega para `handleLink`. |
| **Eventos** | `messageCreate` captura mensagens normais; `setupSlashCommand` registra o comando `/extract`. |

